import '../../domain/catalog/earbuds_catalog.dart';
import '../../domain/catalog/earbuds_model.dart';

/// Artwork per known model. A model without art falls back to the generic
/// placeholder.
abstract final class KzModelArt {
  /// Generated by the project owner (odd/tasks/carol-pro-bluetooth.md L39).
  static const kzCarolPro = 'assets/models/kz_carol_pro.png';

  static final _byModel = {EarbudsCatalog.kzCarolPro: kzCarolPro};

  static String? assetFor(EarbudsModel? model) =>
      model == null ? null : _byModel[model];
}
